from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()  # key -> (value, expiry)
        self.stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0
        }

    def put(self, key, value):
        if self.capacity <= 0:
            return

        now = self.clock()

        if key in self.cache:
            # Replacing an existing key refreshes expiry and recency
            del self.cache[key]
        else:
            # If inserting a NEW key, first remove all expired entries
            expired_keys = [k for k, (v, exp) in self.cache.items() if now >= exp]
            if expired_keys:
                for k in expired_keys:
                    del self.cache[k]
                self.stats["expirations"] += len(expired_keys)

            # If still full, evict LRU (which is the first item in OrderedDict)
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
                self.stats["evictions"] += 1

        self.cache[key] = (value, now + self.ttl)

    def get(self, key, default=None):
        now = self.clock()

        if key not in self.cache:
            self.stats["misses"] += 1
            return default

        value, expiry = self.cache[key]

        if now >= expiry:
            # Expired entry: remove, count as expiration and miss
            del self.cache[key]
            self.stats["expirations"] += 1
            self.stats["misses"] += 1
            return default
        else:
            # Valid entry: mark most recently used
            self.cache.move_to_end(key)
            self.stats["hits"] += 1
            return value

    def __len__(self):
        now = self.clock()
        return sum(1 for k, (v, exp) in self.cache.items() if now < exp)

    def stats(self):
        return self.stats.copy()
